const segmentOverrides={'มากันกี่คน':['มา','กัน','กี่','คน']};
function segmentExample(text){if(segmentOverrides[text])return segmentOverrides[text].map(k=>({...vocabulary[k]}));let i=0,out=[];while(i<text.length){if(/\s/.test(text[i])){i++;continue}const k=vocabularyKeys.find(k=>text.startsWith(k,i));if(!k)throw new Error('単語データ未登録: '+text.slice(i));out.push({...vocabulary[k]});i+=k.length}return out}
function wordsFor(l,i){const ws=segmentExample(l.examples[i].th);for(const w of ws){if(w.th==='เป็น'&&l.id===17)Object.assign(w,{meaning:'〜する技能がある',role:'技能の語',note:'動詞の後ろに置き、やり方を知っていることを示します。'});if(w.th==='อยู่'&&[12,14].includes(l.id))Object.assign(w,{meaning:'〜している',role:'進行・継続の語',note:'この例では動作句の後ろに置き、動作が続くことを示します。'});if(w.th==='ถูก'&&[21,36].includes(l.id))Object.assign(w,{meaning:'安い',role:'価格の状態',note:'この例は受け身ではなく、価格が安い意味。'});if(w.th==='ให้'&&l.id===26&&[1,3].includes(i))Object.assign(w,{meaning:'〜にしてもらう・させる',role:'行為者を導く語',note:'直後の人が、後ろの動作を実際に行います。'});if(w.th==='ที่'&&l.id===24)Object.assign(w,{meaning:'〜する・〜した',role:'名詞修飾をつなぐ語',note:'直前の名詞を、後ろの文で詳しく説明します。'});if(w.th==='มา'&&l.id===24)Object.assign(w,{meaning:'〜してきた',role:'方向を補う語',note:'買う動作が話し手側へ向かうことを示します。'});if(w.th==='ถึง'&&l.id===35)Object.assign(w,{meaning:'たとえ〜でも',role:'譲歩の条件を導く語',note:'この型では到着する意味ではなく、後ろに条件を続けます。'});if(w.th==='ดู'&&l.id===20&&i===1)Object.assign(w,{meaning:'様子を見る',role:'動詞',note:'รอดูで「待って様子を見る」というまとまり。'});if(w.th==='ให้'&&[19,26].includes(l.id)&&!(l.id===26&&[1,3].includes(i)))w.note='この例では「こちら・相手のためにする」という受益を表します。'}return ws}
function wordPanel(l,i){const id=`words-${l.id}-${i}`,ws=wordsFor(l,i);return `<div class="word-control"><button type="button" class="word-toggle" id="${id}-button" aria-expanded="false" aria-controls="${id}" onclick="toggleWords('${id}')">${icon('course')}<span>単語</span><small>意味と役割を見る</small><span class="word-chevron">＋</span></button><div class="word-panel" id="${id}" hidden><div class="word-panel-head">この文を、${ws.length}つの語・表現に分解</div><div class="word-list">${ws.map((w,j)=>`<div class="word-item"><span class="word-order">${j+1}</span><div class="word-main"><span class="word-th" lang="th">${esc(w.th)}</span><span class="word-ro">${esc(w.ro)}</span></div><div class="word-meaning"><b>${esc(w.meaning)}</b><span class="word-role">${esc(w.role)}</span>${w.note?`<p>${esc(w.note)}</p>`:''}</div></div>`).join('')}</div><p class="word-panel-foot">意味のまとまりを保つため、複合語・定型表現はまとめて表示する場合があります。</p></div></div>`}
function toggleWords(id){const p=document.getElementById(id),b=document.getElementById(id+'-button');p.hidden=!p.hidden;b.setAttribute('aria-expanded',String(!p.hidden));b.querySelector('small').textContent=p.hidden?'意味と役割を見る':'単語の解説を閉じる';b.querySelector('.word-chevron').textContent=p.hidden?'＋':'−';if(!p.hidden)annotateReadings(p)}
